//@version=5
indicator("252-bar high line", overlay=true)
n = input.int(252, "Lookback bars", minval=1)
hh = ta.highest(high, n)
var line hiLine = line.new(bar_index, hh, bar_index, hh, extend=extend.right, color=color.red, width=2)
if not na(hh)
    line.set_xy1(hiLine, bar_index - n, hh)
    line.set_xy2(hiLine, bar_index, hh)
plot(hh, "Highest high", color=color.new(color.red, 100))

//@version=5
indicator("Low-to-close line", overlay=true)

n = input.int(60, "Lookback bars", minval=2)
lineColor = input.color(color.blue, "Line colour")
lineWidth = input.int(2, "Line width", minval=1)

// lowest low of the last n bars and how many bars back it sits
ll = ta.lowest(low, n)
offset = ta.lowestbars(low, n)   // 0 or negative

var line conn = line.new(bar_index, low, bar_index, close, color=lineColor, width=lineWidth)

if not na(ll)
    line.set_xy1(conn, bar_index + offset, ll)
    line.set_xy2(conn, bar_index, close)
    line.set_color(conn, lineColor)
    line.set_width(conn, lineWidth)

// hidden plot so the script can be used in alerts
plot(ll, "Lowest low", color=color.new(color.gray, 100))

//@version=5
indicator("100-bar high & low labels", overlay=true)

n = input.int(100, "Lookback bars", minval=2)

hh = ta.highest(high, n)
ll = ta.lowest(low, n)

// how many bars back the extreme sits (0 = current bar)
hiOffset = -ta.highestbars(high, n)
loOffset = -ta.lowestbars(low, n)

var label hiLbl = label.new(bar_index, high, "", style=label.style_label_down, color=color.green, textcolor=color.white, size=size.small)
var label loLbl = label.new(bar_index, low, "", style=label.style_label_up, color=color.red, textcolor=color.white, size=size.small)

if not na(hh)
    label.set_xy(hiLbl, bar_index - hiOffset, hh)
    label.set_text(hiLbl, str.tostring(hh, format.mintick))

if not na(ll)
    label.set_xy(loLbl, bar_index - loOffset, ll)
    label.set_text(loLbl, str.tostring(ll, format.mintick))

plot(hh, "Highest high", color=color.new(color.green, 100))
plot(ll, "Lowest low", color=color.new(color.red, 100))
